151	export function useCmvGraph(cmvId: number | null): CmvGraphData {
152	  const [loading, setLoading] = useState<boolean>(true);
153	  const [cmv, setCmv] = useState<RawCmv | null>(null);
154	  const [fichaData, setFichaData] = useState<RawCmvFicha | null>(null);
155	  const [items, setItems] = useState<RawCmvItem[]>([]);
156	  const [insumos, setInsumos] = useState<RawCmvInsumo[]>([]);
157	  const [embalagens, setEmbalagens] = useState<RawCmvEmbalagem[]>([]);
158	  const [nfEmbalagemItems, setNfEmbalagemItems] = useState<NfEmbalagemItem[]>([]);
159	  const [notas, setNotas] = useState<RawCmvNF[]>([]);
160	  const [nfItems, setNfItems] = useState<RawCmvNFItem[]>([]);
161	  const [positions, setPositions] = useState<Map<string, { x: number; y: number }>>(new Map());
162	
163	  const fetchAll = useCallback(async () => {
164	    if (cmvId === null) {
165	      setLoading(false);
166	      return;
167	    }
168	
169	    setLoading(true);
170	
171	    try {
172	      const [
173	        cmvRes,
174	        itensRes,
175	        insumosRes,
176	        posRes,
177	        nfRes,
178	        nfItensRes,
179	        embalagensRes,
180	        nfEmbalagemRes,
181	      ] = await Promise.all([
182	        supabase
183	          .from('cmv_fichas')
184	          .select('*, fichas_tecnicas(*)')
185	          .eq('id', cmvId)
186	          .maybeSingle(),
187	        supabase
188	          .from('cmv_itens')
189	          .select(
190	            '*, insumos(id,nome,preco_custo,unidade_compra,unidade_producao,categoria,fornecedor_principal), produtos_master(id,nome,preco_custo,unidade_medida), itens_nota_fiscal(id,nome_produto,valor_unitario,unidade,nota_id,notas_fiscais(fornecedor,numero_nota,data_nota))',
191	          )
192	          .eq('cmv_id', cmvId)
193	          .order('ordem'),
194	        supabase
195	          .from('insumos')
196	          .select('id,nome,preco_custo,unidade_compra,unidade_producao,categoria,fornecedor_principal')
197	          .eq('ativo', true)
198	          .order('nome'),
199	        supabase
200	          .from('cmv_canvas_positions')
201	          .select('*')
202	          .eq('cmv_id', cmvId),
203	        supabase
204	          .from('notas_fiscais')
205	          .select('id,fornecedor,numero_nota,valor_total,data_nota')
206	          .order('data_nota', { ascending: false })
207	          .limit(80),
208	        supabase
209	          .from('itens_nota_fiscal')
210	          .select('id,nota_id,insumo_id,nome_produto,valor_unitario,peso_unitario,unidade_base,unidade')
211	          .not('insumo_id', 'is', null)
212	          .limit(2000),
213	        // Catálogo de embalagens: produtos_master com setor = 'EMBALAGENS'
214	        supabase
215	          .from('produtos_master')
216	          .select('id,nome,preco_custo,unidade_medida,setor')
217	          .eq('ativo', true)
218	          .eq('setor', 'EMBALAGENS')
219	          .order('nome'),
220	        // Candidatos de NF para atrelar custo de embalagem
221	        supabase
222	          .from('itens_nota_fiscal')
223	          .select(
224	            'id,nota_id,nome_produto,valor_unitario,unidade,peso_unitario,notas_fiscais(fornecedor,numero_nota,data_nota)',
225	          )
226	          .eq('categoria', 'Embalagens')
227	          .gt('valor_unitario', 0)
228	          .limit(1000),
229	      ]);
230	
231	      // --- cmv_fichas + fichas_tecnicas ---
232	      if (cmvRes.data) {
233	        const raw = cmvRes.data as Record<string, unknown>;
234	        setCmv({
235	          id: raw.id as number,
236	          nome: raw.nome as string,
237	          ficha_tecnica_id: raw.ficha_tecnica_id as number,
238	          status: raw.status as string,
239	          custo_calculado: raw.custo_calculado as number | null,
240	        });
241	
242	        if (raw.fichas_tecnicas) {
243	          const ft = raw.fichas_tecnicas;
244	          const ficha = Array.isArray(ft) ? ft[0] : ft;
245	          if (ficha) {
246	            const f = ficha as Record<string, unknown>;
247	            setFichaData({
248	              id: f.id as number,
249	              nome: f.nome as string,
250	              custo_calculado: f.custo_calculado as number | null,
251	              rendimento_quantidade: f.rendimento_quantidade as number,
252	              rendimento_unidade: f.rendimento_unidade as string,
253	              status: f.status as string,
254	            });
255	          }
256	        }
257	      } else {
258	        setCmv(null);
259	        setFichaData(null);
260	      }
261	
262	      // --- cmv_itens com joins novos ---
263	      if (itensRes.data) {
264	        const mappedItems = (itensRes.data as Record<string, unknown>[]).map((item) => {
265	          // insumo (legado)
266	          const insumosData = item.insumos;
267	          const insumoObj = insumosData
268	            ? Array.isArray(insumosData)
269	              ? insumosData[0]
270	              : insumosData
271	            : undefined;
272	
273	          // produto_master (embalagem escolhida)
274	          const pmData = item.produtos_master;
275	          const pmObj = pmData
276	            ? Array.isArray(pmData)
277	              ? pmData[0]
278	              : pmData
279	            : undefined;
280	          let produtoMaster: ResolvedProdutoMaster | undefined;
281	          if (pmObj) {
282	            const pm = pmObj as Record<string, unknown>;
283	            produtoMaster = {
284	              id: pm.id as number,
285	              nome: pm.nome as string,
286	              preco_custo: pm.preco_custo as number | null,
287	              unidade_medida: pm.unidade_medida as string | null,
288	            };
289	          }
290	
291	          // itens_nota_fiscal (NF travada) com notas_fiscais aninhado
292	          const nfItemData = item.itens_nota_fiscal;
293	          const nfItemObj = nfItemData
294	            ? Array.isArray(nfItemData)
295	              ? nfItemData[0]
296	              : nfItemData
297	            : undefined;
298	          let nfItem: ResolvedNfItem | undefined;
299	          if (nfItemObj) {
300	            const nfi = nfItemObj as Record<string, unknown>;
301	            const nfaNested = nfi.notas_fiscais;
302	            const nfa = nfaNested
303	              ? Array.isArray(nfaNested)
304	                ? (nfaNested[0] as Record<string, unknown>)
305	                : (nfaNested as Record<string, unknown>)
306	              : null;
307	            nfItem = {
308	              id: nfi.id as number,
309	              nome_produto: nfi.nome_produto as string | null,
310	              valor_unitario: nfi.valor_unitario as number | null,
311	              unidade: nfi.unidade as string | null,
312	              nota_id: nfi.nota_id as number,
313	              fornecedor: nfa ? (nfa.fornecedor as string | null) : null,
314	              numero_nota: nfa ? (nfa.numero_nota as string | null) : null,
315	              data_nota: nfa ? (nfa.data_nota as string | null) : null,
316	            };
317	          }
318	
319	          const mapped: RawCmvItem = {
320	            id: item.id as number,
321	            cmv_id: item.cmv_id as number,
322	            tipo: item.tipo as string,
323	            insumo_id: item.insumo_id as number | null,
324	            produto_master_id: (item.produto_master_id as number | null) ?? null,
325	            nf_item_id: (item.nf_item_id as number | null) ?? null,
326	            unidades_por_embalagem: (item.unidades_por_embalagem as number | null) ?? null,
327	            quantidade: item.quantidade as number,
328	            unidade: item.unidade as string,
329	            preco_unitario_esboco: item.preco_unitario_esboco as number | null,
330	            observacao: item.observacao as string | null,
331	            custo_calculado: item.custo_calculado as number | null,
332	            ordem: item.ordem as number,
333	            insumo: insumoObj as RawCmvInsumo | undefined,
334	            produtoMaster,
335	            nfItem,
336	          };
337	          return mapped;
338	        });
339	        setItems(mappedItems);
340	      } else {
341	        setItems([]);
342	      }
343	
344	      // --- insumos ativos (catálogo retrocompat) ---
345	      if (insumosRes.data) {
346	        setInsumos(insumosRes.data as unknown as RawCmvInsumo[]);
347	      }
348	
349	      // --- canvas positions ---
350	      if (posRes.data) {
351	        const newPositions = new Map<string, { x: number; y: number }>();
352	        for (const pos of posRes.data as Record<string, unknown>[]) {
353	          const key = `${pos.node_type}_${pos.node_id}`;
354	          newPositions.set(key, { x: pos.x as number, y: pos.y as number });
355	        }
356	        setPositions(newPositions);
357	      } else {
358	        setPositions(new Map());
359	      }
360	
361	      // --- notas fiscais (retrocompat) ---
362	      if (nfRes.data) {
363	        setNotas(nfRes.data as unknown as RawCmvNF[]);
364	      }
365	
366	      // --- itens NF por insumo (retrocompat) ---
367	      if (nfItensRes.data) {
368	        setNfItems(nfItensRes.data as unknown as RawCmvNFItem[]);
369	      }
370	
371	      // --- catálogo de embalagens ---
372	      if (embalagensRes.data) {
373	        const mapped = (embalagensRes.data as Record<string, unknown>[]).map((p) => ({
374	          id: p.id as number,
375	          nome: p.nome as string,
376	          preco_custo: p.preco_custo as number | null,
377	          unidade_medida: p.unidade_medida as string | null,
378	        }));
379	        setEmbalagens(mapped);
380	      } else {
381	        setEmbalagens([]);
382	      }
383	
384	      // --- itens de NF de embalagem (candidatos para atrelar custo) ---
385	      if (nfEmbalagemRes.data) {
386	        // Ordenar client-side por data_nota desc (embed aninhado impede order no PostgREST)
387	        const mapped = (nfEmbalagemRes.data as Record<string, unknown>[])
388	          .map((row) => {
389	            const nfaNested = row.notas_fiscais;
390	            const nfa = nfaNested
391	              ? Array.isArray(nfaNested)
392	                ? (nfaNested[0] as Record<string, unknown>)
393	                : (nfaNested as Record<string, unknown>)
394	              : null;
395	            const item: NfEmbalagemItem = {
396	              id: row.id as number,
397	              nota_id: row.nota_id as number,
398	              nome_produto: row.nome_produto as string | null,
399	              valor_unitario: row.valor_unitario as number | null,
400	              unidade: row.unidade as string | null,
401	              fornecedor: nfa ? (nfa.fornecedor as string | null) : null,
402	              numero_nota: nfa ? (nfa.numero_nota as string | null) : null,
403	              data_nota: nfa ? (nfa.data_nota as string | null) : null,
404	            };
405	            return item;
406	          })
407	          .sort((a, b) => {
408	            // desc por data_nota (string ISO)
409	            if (!a.data_nota && !b.data_nota) return 0;
410	            if (!a.data_nota) return 1;
411	            if (!b.data_nota) return -1;
412	            return b.data_nota.localeCompare(a.data_nota);
413	          });
414	        setNfEmbalagemItems(mapped);
415	      } else {
416	        setNfEmbalagemItems([]);
417	      }
418	    } catch (err) {
419	      console.error('[useCmvGraph] fetchAll error:', err);
420	    } finally {
421	      setLoading(false);
422	    }
423	  }, [cmvId]);
424	
425	  useEffect(() => {
426	    fetchAll();
427	  }, [fetchAll]);
428	
429	  const savePosition = useCallback(
430	    async (key: string, x: number, y: number) => {
431	      if (cmvId === null) return;
432	
433	      const parsed = parseNodeId(key);
434	      if (!parsed) return;
435	
436	      // Update local state optimistically
437	      setPositions((prev) => {
438	        const next = new Map(prev);
439	        next.set(key, { x, y });
440	        return next;
441	      });
442	
443	      try {
444	        const { error } = await supabase
445	          .from('cmv_canvas_positions')
446	          .upsert(
447	            {
448	              cmv_id: cmvId,
449	              node_type: parsed.type,
450	              node_id: parsed.id,
451	              x,
452	              y,
453	            },
454	            { onConflict: 'cmv_id,node_type,node_id' },
455	          );
456	
457	        if (error) {
458	          console.error('[useCmvGraph] savePosition error:', error);
459	        }
460	      } catch (err) {
461	        console.error('[useCmvGraph] savePosition exception:', err);
462	      }
463	    },
464	    [cmvId],
465	  );
466	
467	  return {
468	    loading,
469	    cmv,
470	    fichaData,
471	    items,
472	    insumos,
473	    embalagens,
474	    nfEmbalagemItems,
475	    notas,
476	    nfItems,
477	    positions,
478	    savePosition,
479	    refetch: fetchAll,
480	  };
481	}
